insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('attention-control-test', 'Attention Control Test', 'Sustained focus and selective attention under distraction — a flanker-style interference task.', convert_from(decode('', 'base64'), 'UTF8'), 'eye', (select id from assessment_categories where key = 'cognitive'), ('timed_questionnaire')::assessment_engine_type, ('medium')::assessment_difficulty, 10, 30, false, ('free')::assessment_access, ('published')::assessment_status)
