insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'attention-control-test'), 'overall', 0, 30, 'Developing', 'The flanking arrows are pulling attention away from the center target more often than not, especially on incongruent trials — a common pattern that improves with practice.', ARRAY['Practice deliberately narrowing your focus to just the center position before glancing at the whole string', convert_from(decode('U2xvdyBkb3duIHZlcnkgc2xpZ2h0bHkgb24gdHJpYWxzIHRoYXQgZmVlbCBsaWtlIHRoZXkgJ2ZsYXNoIGJ5JyDigJQgYSBydXNoZWQgd3JvbmcgYW5zd2VyIGNvc3RzIG1vcmUgdGhhbiBhIGhhbGYtc2Vjb25kIG9mIGNhcmU=', 'base64'), 'UTF8'), convert_from(decode('Tm90aWNlIHdoZXRoZXIgZXJyb3JzIGNsdXN0ZXIgb24gaW5jb25ncnVlbnQgdHJpYWxzIHNwZWNpZmljYWxseSDigJQgdGhhdCdzIHRoZSBpbnRlcmZlcmVuY2UgZWZmZWN0LCBhbmQgaXQncyBub3JtYWwgZWFybHkgb24=', 'base64'), 'UTF8')]::text[], NULL, 1);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'attention-control-test'), 'overall', 31, 50, 'Average', 'Congruent trials are handled well, but incongruent ones (where the flankers point the other way) cost accuracy or speed.', ARRAY['Practice sets weighted toward incongruent trials specifically to build resistance to the interference effect', 'Keep your gaze centered rather than scanning the whole arrow string left to right']::text[], NULL, 2);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'attention-control-test'), 'overall', 51, 70, 'Strong', 'Reliable accuracy across both congruent and incongruent trials, with a modest speed cost on the harder ones — a normal, healthy interference pattern.', ARRAY['Push response speed further on congruent trials, where accuracy is already solid', 'This level of selective attention transfers directly to work environments full of visual distraction']::text[], NULL, 3);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'attention-control-test'), 'overall', 71, 85, 'Very Strong', 'Fast and accurate on nearly every trial, including incongruent ones — minimal interference from the flanking distractors.', ARRAY['This is a strong, genuine selective-attention advantage — notice where it helps most in daily distraction-heavy tasks', 'Try the task again after a mentally fatiguing day to see how much the effect holds up under load']::text[], NULL, 4);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'attention-control-test'), 'overall', 86, 100, 'Exceptional', 'Near-perfect speed and accuracy on every trial type — the flanking distractors barely register.', ARRAY['This level of attentional control is a genuine asset in high-distraction, high-stakes environments', 'Consider roles or tasks that specifically reward sustained selective attention under interference']::text[], NULL, 5);
