insert into assessments (slug, title, short_description, long_description, icon, category_id, engine_type, difficulty, estimated_duration_minutes, question_count, featured, access, status) values ('creative-divergent-thinking', 'Creative Divergent Thinking', 'Alternative-uses and idea-fluency tasks that measure how many genuinely different directions you can generate.', 'Creative Divergent Thinking combines two classic, complementary creativity paradigms. The Alternative Uses Task (Guilford, 1967) asks you to generate as many different uses as you can for an everyday object — the foundational measure of idea fluency and divergent thinking, scored here by AI interpretation rather than a right/wrong answer, since the point is open-ended generation. The Remote Associates Test (Mednick, 1962) asks you to find the single word that connects three seemingly unrelated words — a convergent-creativity measure with objectively correct answers, scored deterministically.', 'shuffle', (select id from assessment_categories where key = 'creative'), ('hybrid')::assessment_engine_type, ('medium')::assessment_difficulty, 15, 10, false, ('premium')::assessment_access, ('published')::assessment_status)
insert into scoring_dimensions (assessment_id, key, label, description, contributes_to_brain_profile, brain_profile_dimension_key, "order") values ((select id from assessments where slug = 'creative-divergent-thinking'), 'convergent-creativity', 'Remote Associates (Convergent Creativity)', 'Finding the single connecting concept across three unrelated words.', true, 'creative', 1)
