insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'critical-thinking-depth'), 'overall', 0, 30, 'Developing', 'Critical-thinking fundamentals are still forming — conclusions are often accepted or rejected based on plausibility rather than what the evidence actually supports.', ARRAY[convert_from(decode('UHJhY3RpY2Ugc2VwYXJhdGluZyAnc3RhdGVkJyBmcm9tICdhc3N1bWVkJyBpbiBldmVyeWRheSBhcmd1bWVudHMgeW91IHJlYWQ=', 'base64'), 'UTF8'), 'Work through simple syllogisms and check your answer against formal validity, not intuition', 'When reading an argument, explicitly list the unstated assumptions it depends on']::text[], NULL, 1);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'critical-thinking-depth'), 'overall', 31, 50, 'Average', 'Solid on straightforward inference and deduction, but multi-step arguments or subtle unstated assumptions still catch you out.', ARRAY[convert_from(decode('UHJhY3RpY2UgdGhlICdtdXN0IGJlIHRydWUgdnMuIG1pZ2h0IGJlIHRydWUgdnMuIGNhbm5vdCBiZSBkZXRlcm1pbmVkJyBkaXN0aW5jdGlvbiBkZWxpYmVyYXRlbHk=', 'base64'), 'UTF8'), convert_from(decode('UmVhZCBvcGluaW9uIHBpZWNlcyBhbmQgaWRlbnRpZnkgdGhlIHN0cm9uZ2VzdCBjb3VudGVyLWFyZ3VtZW50IGJlZm9yZSBldmFsdWF0aW5nIHRoZSBhdXRob3IncyBjYXNl', 'base64'), 'UTF8'), 'Slow down on assumption-recognition items — the obvious-sounding option is often a distractor']::text[], NULL, 2);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'critical-thinking-depth'), 'overall', 51, 70, 'Strong', convert_from(decode('Q29uc2lzdGVudGx5IHNlcGFyYXRlcyB2YWxpZCBpbmZlcmVuY2UgZnJvbSBwbGF1c2libGUtc291bmRpbmcgc3BlY3VsYXRpb24sIGFuZCBnZW5lcmFsbHkgc3BvdHMgdGhlIGFyZ3VtZW50J3MgcmVhbCB3ZWFrIHBvaW50Lg==', 'base64'), 'UTF8'), ARRAY['Practice evaluating arguments on relevance and importance, not just whether you agree with the conclusion', 'Seek out longer, multi-premise deductive chains to sharpen precision']::text[], NULL, 3);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'critical-thinking-depth'), 'overall', 71, 85, 'Very Strong', convert_from(decode('UmVsaWFibHkgZGlzdGluZ3Vpc2hlcyB2YWxpZCByZWFzb25pbmcgZnJvbSByaGV0b3JpYyBhY3Jvc3MgYWxsIGZpdmUgc2tpbGxzLCByYXJlbHkgc3dheWVkIGJ5IGFuIGFyZ3VtZW50J3MgY29uY2x1c2lvbiB3aGVuIGp1ZGdpbmcgaXRzIHN0cnVjdHVyZS4=', 'base64'), 'UTF8'), ARRAY['Apply this discipline to real decisions with incomplete information — write out the inference chain explicitly', 'Practice constructing counter-arguments that meet the same evaluation-of-arguments bar you hold others to']::text[], NULL, 4);
insert into result_ranges (assessment_id, dimension_key, min_score, max_score, title, description, recommendations, icon, "order") values ((select id from assessments where slug = 'critical-thinking-depth'), 'overall', 86, 100, 'Exceptional', 'Expert-level critical thinking — evidence, assumptions, and validity are evaluated independently of what conclusion is more comfortable or expected.', ARRAY[convert_from(decode('VGhpcyBpcyB0aGUgc2tpbGwgc2V0IGxlZ2FsLCBhbmFseXRpY2FsLCBhbmQgcmVzZWFyY2ggcm9sZXMgYXJlIGJ1aWx0IG9uIOKAlCBjb25zaWRlciB3aGVyZSBpdCdzIG1vc3QgbGV2ZXJhZ2Vk', 'base64'), 'UTF8'), 'Mentor others on the difference between a strong argument and one that merely sounds confident']::text[], NULL, 5);
