-- abstract-reasoning-pro (abstract-reasoning-pro.json)
  on conflict (slug) do update set title = excluded.title, short_description = excluded.short_description, long_description = excluded.long_description, icon = excluded.icon, category_id = excluded.category_id, engine_type = excluded.engine_type, difficulty = excluded.difficulty, estimated_duration_minutes = excluded.estimated_duration_minutes, question_count = excluded.question_count, featured = excluded.featured, access = excluded.access, status = excluded.status;
  on conflict (assessment_id, key) do update set label = excluded.label, description = excluded.description, contributes_to_brain_profile = excluded.contributes_to_brain_profile, brain_profile_dimension_key = excluded.brain_profile_dimension_key, "order" = excluded."order";
delete from result_ranges where assessment_id = (select id from assessments where slug = 'abstract-reasoning-pro');
delete from brain_profile_contribution_rules where assessment_id = (select id from assessments where slug = 'abstract-reasoning-pro');
  select a.id, coalesce((select max(v.version_number) from assessment_versions v where v.assessment_id = a.id), 0) + 1, 'published'::assessment_status, (convert_from(decode('', 'base64'), 'UTF8'))::jsonb, now()
  from assessments a where a.slug = 'abstract-reasoning-pro';
update assessments set current_version_id = (select v.id from assessment_versions v where v.assessment_id = assessments.id order by v.version_number desc limit 1) where slug = 'abstract-reasoning-pro';

